describe("doctests of sympy.concrete.gosper", () => {
  it("gosper_normal(4*n+5, 2*(4*n+1)*(2*n+3), n, polys=False)", () => {
    const n = new Sym('n');
    const v1 = gosperNormal(add(Rational.of(5n, 1n, { gcd: 1n }), mul(Rational.of(4n, 1n, { gcd: 1n }), n)), mul(add(Rational.of(2n, 1n, { gcd: 1n }), mul(Rational.of(8n, 1n, { gcd: 1n }), n)), add(Rational.of(3n, 1n, { gcd: 1n }), mul(Rational.of(2n, 1n, { gcd: 1n }), n))), n, { polys: false });
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(1/4, n + 3/2, n + 1/4)')).toBe(true);
  });
  it("gosper_sum(f, (k, 0, n))", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(gosperSum(mul(pow(fn('factorial', [add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(2n, 1n, { gcd: 1n }), k))]), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(4n, 1n, { gcd: 1n }), k)), fn('factorial', [k])), [k, 0, n]))).toBe('(-factorial(n) + 2*factorial(2*n + 1))/factorial(2*n + 1)');
  });
  it("gosper_sum(f, (k, 3, n))", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(gosperSum(mul(pow(fn('factorial', [add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(2n, 1n, { gcd: 1n }), k))]), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(4n, 1n, { gcd: 1n }), k)), fn('factorial', [k])), [k, 3, n]))).toBe('(-60*factorial(n) + factorial(2*n + 1))/(60*factorial(2*n + 1))');
  });
  it("gosper_term((4*n + 1)*factorial(n)/factorial(2*n + 1), n)", () => {
    const n = new Sym('n');
    expect(sympyStr(gosperTerm(mul(pow(fn('factorial', [add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(2n, 1n, { gcd: 1n }), n))]), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(4n, 1n, { gcd: 1n }), n)), fn('factorial', [n])), n))).toBe('(-n - 1/2)/(n + 1/4)');
  });
});

